INSERT IGNORE INTO ai_chat_references (id, source, speaker, content, spoken_at) VALUES ('ref_kakao_0001', 'kakao_cho', '국어농장주/조창훈', '[속보]이규민 평가원장 사임 "6월 모평 책임…수험생·학부모에 죄송"\n출처 : 뉴시스 | 네이버 뉴스', '2023-06-19 16:32:00');
INSERT IGNORE INTO ai_chat_references (id, source, speaker, content, spoken_at) VALUES ('ref_kakao_0002', 'kakao_cho', '국어농장주/조창훈', '평가원장님 포함 평가원 직원분들의 자괴감이 몹시 클 것 같습니다', '2023-06-19 17:02:00');
INSERT IGNORE INTO ai_chat_references (id, source, speaker, content, spoken_at) VALUES ('ref_kakao_0003', 'kakao_cho', '국어농장주/조창훈', '입시 전문가나 타 과목 선생님들은\n난이도에 대한 걱정들을 하시지만...\n전 난이도는 사실 크게 상관 없다고 생각합니다\n처음에 난이도 얘긴 줄 알고 쉽게 나오든 어렵게 나오든 흔들릴 필요 없다는 주제로 보이스룸을 하려 했다가\n어제 저녁 기사들을 보고...\n엉뚱하게 비문학... 출제를 걸고 넘어진 것을 확인한 후로는\n평가원에서 도대체 국어(타과목은 아예 예를 들지 않았지요. 국어 비문학의 예만 들었어요ㅠ) 영역에서 특히 비문학을 어떻게 출제하라는 건지 도저히 감이 안 왔고....\n국장 경질 소식에 교육과정과의 연결성을 대통령께 설명하는 것이 먹히지 않겠구나... 싶으니까... 평가원에서 아무것도 할 수 없는 상황이라는 걸 느꼈습니다\n심지어 평가원을 사교육과 이권 카르텔이라 몰고 가는 모습까지 보니... 제가 평가원 관계자여도 어마어마한 자괴감이 들 것 같았습니다\n오전에 언급했듯 수능 국어(특히 비문학)는 수능의 원 취지에 잘 부합하는 좋은 문제들입니다. 많은 비용과 연구를 거', '2023-06-19 17:13:00');
INSERT IGNORE INTO ai_chat_references (id, source, speaker, content, spoken_at) VALUES ('ref_kakao_0004', 'kakao_cho', '국어농장주/조창훈', '오늘 설명회 참석해주신 모든 분께 감사드립니다^^\n이제 정리 마무리하고 퇴근합니다\n늘 노력 발전하는 국어농장이 되겠습니다', '2023-06-19 21:35:00');
