INSERT IGNORE INTO ai_chat_references (id, source, speaker, content, spoken_at) VALUES ('ref_kakao_0124', 'kakao_humor', '국어농장주/조창훈', 'ㅎㅎㅎㅎ 이번 주 교재 작업도 이제 마무리돼 가네여', '2023-07-22 07:17:00');
INSERT IGNORE INTO ai_chat_references (id, source, speaker, content, spoken_at) VALUES ('ref_kakao_0125', 'kakao_cho', '국어농장주/조창훈', '글로 잠깐 설명드리자면...\n먼저\n영수가 학생이다... 를 P로 놓고\n영수가 공부를 해야 한다...를 Q로 놓습니다\n(조건문이 나오면 일단 무조건 P Q로 바꿔서 생각합니다)\nP이면 Q이다...의 형태는 충분조건이라고 하구요\n벤다이어그램을 그리면...(이 부분은 생략할게여)\n여튼 쉽게 말씀 드리면\n로또 당첨되면(P) 농장방에 100만 원씩 뿌리겠다(Q)\n가 참이라고 할 때\n위 문장이\n(1) 제가 로또 당첨됐다(P)는 걸 뜻하진 않지요 - 알 수 없음\n(2) 한편으론 로또 당첨 안 됐을 때(~P)에 대해선 언급 안 했으니 로또 당첨 안 된 상태에서 제가 100만 원씩 뿌릴지 안 뿌릴지도 알 수 없지요 (로또가 당첨되지 않아도 나스닥...상장이 되면... 코스닥 상장이라도;;; 뿌릴지도 모릅니다...)\nP이든 ~P이든은 P와 상관없이란 뜻이고... P의 참거짓을 무시한단 뜻이에요... 그래서\n(3) 제가 로또가 되든 안 되든 100만 원씩 뿌리겠다는 말은\n무조건 100만', '2023-07-22 08:00:00');
